contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint depAmt, uint sendAmt, uint withdrawAmt) public payable {
        require(address(this).balance >= depAmt);
        c.deposit{value: depAmt}();
        uint credit0 = depAmt;
        uint bal0 = address(this).balance;
        require(address(this).balance >= sendAmt);
        // sendAmt is intentionally donated to c without creating credit;
        // it can only change address(c).balance, not credit[this].
        (bool okDonate, ) = address(c).call{value: sendAmt}("");
        require(okDonate);
        uint cBalBefore = address(c).balance;
        require(withdrawAmt <= credit0);
        uint balBefore = address(this).balance;
        uint cBalBefore2 = cBalBefore;
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }
        if (cBalBefore2 >= withdrawAmt) {
            assert(!reverted && c.credit(address(this)) == credit0 - withdrawAmt && address(this).balance == balBefore + withdrawAmt && address(c).balance == cBalBefore2 - withdrawAmt);
        } else {
            assert(reverted && c.credit(address(this)) == credit0 && address(this).balance == balBefore && address(c).balance == cBalBefore2);
        }
    }

    receive() external payable {}
}

